#include "server-storage.h"

#include <fstream>
#include <sstream>

namespace fs = std::filesystem;

static json read_json_file(const fs::path & path) {
    std::ifstream f(path, std::ios::binary);
    if (!f) {
        throw std::runtime_error("failed to open file: " + fs_path_to_utf8(path));
    }
    std::stringstream ss;
    ss << f.rdbuf();
    return json::parse(ss.str());
}

// ids are generated by the UI (uuid), anything else could escape the storage directory
static void validate_id(const std::string & id) {
    if (id.empty() || id.size() > 64) {
        throw std::invalid_argument("invalid conversation id");
    }
    for (char c : id) {
        if (!std::isalnum((unsigned char) c) && c != '-' && c != '_') {
            throw std::invalid_argument("invalid conversation id");
        }
    }
}

static server_http_res_ptr res_json(int status, const json & data) {
    auto res = std::make_unique<server_http_res>();
    res->status = status;
    res->data   = safe_json_to_str(data);
    return res;
}

fs::path server_storage::conversation_path(const std::string & id) const {
    return dir / "conversations" / fs::u8path(id + ".json");
}

void server_storage::load_index() {
    const fs::path index_path = dir / "index.json";

    if (fs::exists(index_path)) {
        try {
            index = read_json_file(index_path);
            if (index.is_object()) {
                return;
            }
        } catch (const std::exception & e) {
            SRV_WRN("failed to read %s, rebuilding it: %s\n", fs_path_to_utf8(index_path).c_str(), e.what());
        }
    }

    index = json::object();
    for (const auto & entry : fs::directory_iterator(dir / "conversations")) {
        if (!entry.is_regular_file() || entry.path().extension() != ".json") {
            continue;
        }
        try {
            const json doc = read_json_file(entry.path());
            const std::string id = doc.at("conv").at("id").get<std::string>();
            index[id] = { { "rev", doc.value("rev", 0) }, { "conv", doc.at("conv") } };
        } catch (const std::exception & e) {
            SRV_WRN("skipping unreadable conversation %s: %s\n", fs_path_to_utf8(entry.path()).c_str(), e.what());
        }
    }
    save_index();
}

void server_storage::save_index() const {
    fs_write_atomic(dir / "index.json", safe_json_to_str(index));
}

void server_storage::setup(const fs::path & storage_dir) {
    dir = storage_dir;

    std::error_code ec;
    common_create_directories(dir / "conversations", ec);
    if (ec) {
        throw std::runtime_error("failed to create UI storage directory: " + fs_path_to_utf8(dir));
    }
    load_index();

    SRV_INF("UI storage in %s (%zu conversations)\n", fs_path_to_utf8(dir).c_str(), index.size());

    handle_list = [this](const server_http_req &) {
        std::lock_guard<std::mutex> lock(mtx);
        json list = json::array();
        for (const auto & [id, entry] : index.items()) {
            list.push_back(entry);
        }
        return res_json(200, list);
    };

    handle_get = [this](const server_http_req & req) {
        const std::string id = req.get_param("id");
        validate_id(id);

        std::lock_guard<std::mutex> lock(mtx);
        if (!index.contains(id)) {
            return res_json(404, { { "error", format_error_response("conversation not found", ERROR_TYPE_NOT_FOUND) } });
        }
        return res_json(200, read_json_file(conversation_path(id)));
    };

    // the body carries the revision it was based on, 0 for a new conversation
    handle_put = [this](const server_http_req & req) {
        const std::string id = req.get_param("id");
        validate_id(id);

        const json body = json::parse(req.body);
        const int  rev  = body.at("rev").get<int>();
        const json & conv     = body.at("conv");
        const json & messages = body.at("messages");
        if (!conv.is_object() || conv.value("id", "") != id || !messages.is_array()) {
            throw std::invalid_argument("expected { rev, conv, messages } with conv.id matching the path");
        }

        std::lock_guard<std::mutex> lock(mtx);
        const int current = index.contains(id) ? index[id].value("rev", 0) : 0;
        if (rev != current) {
            json error = { { "code", 409 }, { "message", "conversation was modified by another client" }, { "type", "conflict_error" } };
            return res_json(409, { { "error", error }, { "rev", current } });
        }

        const json doc = { { "rev", current + 1 }, { "conv", conv }, { "messages", messages } };
        fs_write_atomic(conversation_path(id), safe_json_to_str(doc));
        index[id] = { { "rev", current + 1 }, { "conv", conv } };
        save_index();

        return res_json(200, { { "rev", current + 1 } });
    };

    handle_delete = [this](const server_http_req & req) {
        const std::string id = req.get_param("id");
        validate_id(id);

        std::lock_guard<std::mutex> lock(mtx);
        std::error_code ec;
        fs::remove(conversation_path(id), ec);
        if (index.contains(id)) {
            index.erase(id);
            save_index();
        }
        return res_json(200, json::object());
    };

    handle_get_settings = [this](const server_http_req &) {
        std::lock_guard<std::mutex> lock(mtx);
        const fs::path path = dir / "settings.json";
        return res_json(200, fs::exists(path) ? read_json_file(path) : json::object());
    };

    // merges per key, so two clients changing different settings do not overwrite each other
    handle_put_settings = [this](const server_http_req & req) {
        const json body = json::parse(req.body);
        const json set    = body.value("set", json::object());
        const json remove = body.value("remove", json::array());
        if (!set.is_object() || !remove.is_array()) {
            throw std::invalid_argument("expected { set: { key: value }, remove: [key] }");
        }

        std::lock_guard<std::mutex> lock(mtx);
        const fs::path path = dir / "settings.json";
        json settings = fs::exists(path) ? read_json_file(path) : json::object();
        for (const auto & [key, value] : set.items()) {
            if (!value.is_string()) {
                throw std::invalid_argument("setting values must be strings");
            }
            settings[key] = value;
        }
        for (const auto & key : remove) {
            settings.erase(key.get<std::string>());
        }
        fs_write_atomic(path, safe_json_to_str(settings));

        return res_json(200, settings);
    };
}
